import React, { useEffect, useRef, useState } from 'react';
import { Badge, Spinner } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { permissionContainer } from './formFieldData';
import Table from '../../components/Table';
import { dateConversion, deleteData, findArrObj, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import {
    createPermissionRequest, getStaffRequest, getPermissionRequest, resetCreatePermission, resetGetPermission, resetUpdatePermission, resetGetStaff, updatePermissionRequest, resetGetBranch, getBranchRequest, updateStaffAttendanceRequest,
    resetUpdateStaffAttendance
} from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks'
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';
import moment from 'moment';
import { useNavigate } from 'react-router-dom';

let isEdit = false;

function Index() {

    usePageTitle({
        title: 'Master',
        breadCrumbItems: [
            {
                path: '/view/permission',
                label: 'Master',
            },
            {
                path: '/view/permission',
                label: 'Permission',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();

    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', 'Master');
    const accessIds = (pageAccessData?.[0]?.children.find(val => val.label == "Permission").access || '')
        .split(',')
        .map(id => id.trim());
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)
    const navigate = useNavigate();

    const {
        getBranchSuccess, getBranchList, getBranchFailure,
        getPermissionSuccess, getPermissionList, getPermissionFailure,
        createPermissionSuccess, createPermissionData, createPermissionFailure,
        updatePermissionSuccess, updatePermissionData, updatePermissionFailure,
        errorMessage, getStaffSuccess,
        getStaffList,
        getStaffFailure,
        updateStaffAttendanceSuccess,
        updateStaffAttendanceFailure,

    } = appSelector((state) => ({
        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,

        getPermissionSuccess: state.permissionReducer.getPermissionSuccess,
        getPermissionList: state.permissionReducer.getPermissionList,
        getPermissionFailure: state.permissionReducer.getPermissionFailure,

        getActivitySuccess: state.activityReducer.getActivitySuccess,
        getActivityList: state.activityReducer.getActivityList,
        getActivityFailure: state.activityReducer.getActivityFailure,

        createPermissionSuccess: state.permissionReducer.createPermissionSuccess,
        createPermissionData: state.permissionReducer.createPermissionData,
        createPermissionFailure: state.permissionReducer.createPermissionFailure,

        updatePermissionSuccess: state.permissionReducer.updatePermissionSuccess,
        updatePermissionData: state.permissionReducer.updatePermissionData,
        updatePermissionFailure: state.permissionReducer.updatePermissionFailure,

        errorMessage: state.permissionReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Date',
            accessor: 'permissionDate',
            Cell: ({ row }) => {
                return (
                    <div>
                        {dateConversion(row.original.permissionDate, "DD-MM-YYYY")}
                    </div>
                )
            },
        },
        {
            Header: 'Staff Name',
            accessor: 'staffName',
            sort: true,
        },
        {
            Header: 'Permission Type',
            accessor: 'permissionTypeName',
            sort: true,
        },
        {
            Header: 'Status',
            accessor: 'statusId',
            Cell: ({ row }) => (
                <Badge
                    bg={
                        row.original.statusId === 30
                            ? 'danger'
                            : row.original.statusId === 28
                                ? 'primary'
                                : 'success'
                    }>
                    {row.original.statusId === 30
                        ? 'Cancelled'
                        : row.original.statusId === 28
                            ? 'Request'
                            : 'Approved'}
                </Badge>
            ),
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                const passData = {
                    isPermission: row.original.permissionTypeId == 39 ? false : true,
                    isLeave: row.original.permissionTypeId == 39 ? true : false,
                    staffName: row.original?.staffName || "",
                    designationName: row.original?.designationName,
                    typeName: row.original?.permissionTypeName,
                    fromDate: row.original?.permissionDate,
                    toDate: false,
                    spokenStaffName: row.original?.spokenStaffName,
                    spokenDesignationName: row.original?.spokenDesignationName,
                    spokenTime: row.original?.spokenTime,
                    spokenDate: row.original?.spokenDate,
                    reason: row.original?.reason,

                }
                return (
                    <div>
                        {
                            (roleIdforRole == 1 || _.includes(accessIds, '2')) &&
                            <span className="text-success  me-2 cursor-pointer" onClick={() => onEditForm(row.original, row.index)}>
                                <i className={'fe-edit-1'}></i>
                            </span>
                        }

                        {roleIdforRole == 1 && row.original.statusId === 28 && (
                            <span>
                                <span
                                    className={`text-success me-2 cursor-pointer`}
                                    onClick={() =>
                                        showConfirmationDialog(
                                            'You want to Approved?',
                                            () => onStatusForm(row.original, row.index, 29),
                                            'Yes'
                                        )
                                    }>
                                    <i className={'fe-thumbs-up'}></i>
                                </span>

                                <span
                                    className={`text-danger cursor-pointer`}
                                    onClick={() =>
                                        showConfirmationDialog(
                                            'You want to Cancelled?',
                                            () => onStatusForm(row.original, row.index, 30),
                                            'Yes'
                                        )
                                    }>
                                    <i className={'fe-thumbs-down'}></i>
                                </span>
                            </span>
                        )}

                        {
                            row.original.statusId == 29 && (
                                <>
                                    {
                                        row.original.permissionTypeId == 39 ?
                                            <span className="text-success  me-2 cursor-pointer"
                                                onClick={() => navigate('/leave-slip-report', { state: passData })}>
                                                <i className={'fe-printer'} style={{ fontSize: '19px' }}></i>
                                            </span> :
                                            <span className="text-success  me-2 cursor-pointer"
                                                onClick={() => navigate('/permission-report', { state: passData })}>
                                                <i className={'fe-printer'} style={{ fontSize: '19px' }}></i>
                                            </span>
                                    }
                                </>
                            )
                        }
                    </div>
                );
            },
        },
    ];

    const [state, setState] = useState({
        spokenDate: moment().format("YYYY-MM-DD"),
        spokenTime: moment().format("HH:mm"),
        minmumFrom: moment().format("YYYY-MM-DD"),
        minmumTo: moment().format("YYYY-MM-DD"),
    });
    const [parentList, setParentList] = useState([]);
    const [optionListState, setOptionListState] = useState({
        staffList: [],
        spokenStaffList: [],
        permissionTypeList: [
            { permissionTypeId: 37, permissionTypeName: '1hr' },
            // { permissionTypeId: 38, permissionTypeName: '2hr' },
            // { permissionTypeId: 39, permissionTypeName: 'Half-Day' },
        ],
    })
    const [selectedItem, setSelectedItem] = useState({});
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [formContain, setFormContain] = useState(permissionContainer);
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);

    const errorHandle = useRef();


    useEffect(() => {
        setState({
            ...state,
            minmumTo: state?.permissionDate,
        })
    }, [state?.permissionDate, state?.spokenDate])

    useEffect(() => {
        setIsLoading(true)
        const req = {
            branchId: branchIdforRole
        }
        dispatch(getPermissionRequest(roleIdforRole != 1 && req));
        dispatch(getStaffRequest(req));
        dispatch(getBranchRequest());
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = permissionContainer;
            const updatedFormFields = _.filter(
                permissionContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [permissionContainer, roleIdforRole]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: getBranchList
            })
            dispatch(resetGetBranch())
        } else if (getBranchFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: [],
            })
            dispatch(resetGetBranch())
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getStaffSuccess) {
            setIsLoading(false);
            const remainingStaffList = deleteData(getStaffList, state?.staffId, "staffId");
            setOptionListState({
                ...optionListState,
                staffList: getStaffList,
                spokenStaffList: remainingStaffList
            });
            dispatch(resetGetStaff());
        } else if (getStaffFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                staffList: [],
            });
            dispatch(resetGetStaff());
        }
    }, [getStaffSuccess, getStaffFailure]);

    useEffect(() => {
        if (getPermissionSuccess) {
            setIsLoading(false)
            setParentList(getPermissionList)
            dispatch(resetGetPermission())
        } else if (getPermissionFailure) {
            setIsLoading(false)
            setParentList([])
            dispatch(resetGetPermission())
        }
    }, [getPermissionSuccess, getPermissionFailure]);

    useEffect(() => {
        if (createPermissionSuccess) {
            const temp_state = [createPermissionData[0], ...parentList];
            setParentList(temp_state)
            showMessage('success', 'Created Successfully');
            closeModel()
            dispatch(resetCreatePermission())
        } else if (createPermissionFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreatePermission())
        }
    }, [createPermissionSuccess, createPermissionFailure]);

    useEffect(() => {
        if (updatePermissionSuccess) {
            const temp_state = [...parentList];
            temp_state[selectedIndex] = updatePermissionData[0];
            setParentList(temp_state)
            isEdit && showMessage('success', 'Updated Successfully');
            closeModel()
            dispatch(resetUpdatePermission())
        } else if (updatePermissionFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdatePermission())
        }
    }, [updatePermissionSuccess, updatePermissionFailure]);

    const closeModel = () => {
        isEdit = false;
        onFormClear()
        setModal(false)
    }

    const onFormClear = () => {
        setState({
            ...state,
            permissionDate: '',
            staffId: '',
            spokenDate: moment().format("YYYY-MM-DD"),
            spokenTime: moment().format("HH:mm"),
            spokenStaffId: '',
            branchId: '',
            permissionTypeId: '',
            reason: '',
        });
        setOptionListState({
            ...optionListState,
            spokenStaffList: [],
        });
    };

    const createModel = () => {
        onFormClear()
        isEdit = false;
        setModal(true)
    };

    const onEditForm = async (data, index) => {
        setState({
            ...state,
            staffId: data?.staffId || "",
            reason: data?.reason || "",
            spokenDate: data.spokenDate ? dateConversion(data.spokenDate, "YYYY-MM-DD") : "",
            spokenTime: data?.spokenTime || moment().format("HH:mm"),
            spokenStaffId: data?.spokenStaffId || "",
            branchId: data?.staffBranchId || "",
            permissionTypeId: data?.permissionTypeId || "",
            permissionDate: data.permissionDate ? dateConversion(data.permissionDate, "YYYY-MM-DD") : ""
        });
        const branchFilter = {
            branchId: data?.staffBranchId
        }
        dispatch(getStaffRequest(branchFilter));
        isEdit = true;
        setSelectedItem(data)
        setSelectedIndex(index)
        setModal(true)
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    }

    const onFormSubmit = async () => {
        const staffPermissions = parentList.filter(perm =>
            perm.staffId === state.staffId &&
            perm.statusId === 29
        );

        const currentMonth = moment(state.permissionDate).month();
        const currentYear = moment(state.permissionDate).year();

        const monthlyApprovedPermissions = staffPermissions.filter(perm => {
            const permDate = moment(perm.permissionDate);
            return permDate.month() === currentMonth &&
                permDate.year() === currentYear;
        });

        const monthlyApprovedCount = monthlyApprovedPermissions.length;

        if (monthlyApprovedCount % 3 === 2) {
            const permissionDates = monthlyApprovedPermissions
                .map(p => dateConversion(p.permissionDate, "DD-MM-YYYY"))
                .join(", ");

            const newPermissionDate = dateConversion(state.permissionDate, "DD-MM-YYYY");

            showConfirmationDialog(
                `<strong>Permission Limit Warning</strong><br/><br/>` +
                `Staff already has <strong>${monthlyApprovedCount}</strong> approved permissions this month (<em>${permissionDates}</em>).<br/><br/>` +
                `Approving this new permission for <strong>${newPermissionDate}</strong> will:<br/>` +
                `- Count as their 3rd permission<br/>` +
                `- Automatically convert to a half-day leave<br/>` +
                `- Affect their leave balance<br/><br/>` +
                `Are you sure you want to continue?`,
                proceedWithPermission,
                'Confirm'
            );
            return;
        }

        proceedWithPermission();
    };

    const proceedWithPermission = () => {
        const submitRequest = {
            staffId: state?.staffId || "",
            reason: state?.reason || "",
            spokenDate: state?.spokenDate ? dateConversion(state.spokenDate, "YYYY-MM-DD") : "",
            spokenTime: state?.spokenTime || moment().format("HH:mm"),
            spokenStaffId: state?.spokenStaffId || "",
            permissionTypeId: state?.permissionTypeId || "",
            permissionStatusId: 28,
            permissionDate: state.permissionDate ? dateConversion(state.permissionDate, "YYYY-MM-DD") : "",
            branchId: branchIdforRole,
        };

        if (isEdit) {
            dispatch(updatePermissionRequest(submitRequest, selectedItem.permissionId));
        } else {
            dispatch(createPermissionRequest(submitRequest));
        }
    };

    const onBranchChange = async (option, formName, formUniqueKey, formDisplayKey) => {
        const branchFilter = {
            branchId: option[formUniqueKey]
        }
        setState({
            ...state,
            [formName]: option[formUniqueKey]
        })

        dispatch(getStaffRequest(branchFilter));
    }

    const onStaffChange = async (option, formName, formUniqueKey, formDisplayKey) => {
        setState({
            ...state,
            [formName]: option[formUniqueKey]
        })
        const remainingStaffList = await deleteData(optionListState.staffList, option[formUniqueKey], formUniqueKey);
        setOptionListState({
            ...optionListState,
            spokenStaffList: remainingStaffList
        })
    }

    const onStatusForm = async (data, index, activeChecker) => {
        if (activeChecker === 29) {
            const staffPermissions = parentList.filter(perm =>
                perm.staffId === data.staffId &&
                perm.statusId === 29
            );
            const currentMonth = moment(data.permissionDate).month();
            const currentYear = moment(data.permissionDate).year();

            const monthlyApprovedPermissions = staffPermissions.filter(perm => {
                const permDate = moment(perm.permissionDate);
                return permDate.month() === currentMonth &&
                    permDate.year() === currentYear;
            });

            const monthlyApprovedCount = monthlyApprovedPermissions.length;

            if ((monthlyApprovedCount + 1) % 3 === 0) {
                const attendanceUpdate = {
                    staffAttendance: [{
                        staffId: data.staffId,
                        attendanceStatusId: 2,
                        attendanceDate: moment(data.permissionDate).format('YYYY-MM-DD'),
                        branchId: data.staffBranchId,
                        departmentId: data.departmentId
                    }]
                };

                await dispatch(updateStaffAttendanceRequest(attendanceUpdate));
                if (updateStaffAttendanceFailure) {
                    showMessage('error', 'Failed to update attendance to half-day');
                    dispatch(resetUpdateStaffAttendance());
                    return;
                }
            }
        }

        const submitRequest = {
            statusId: activeChecker,
            isActive: activeChecker == 30 ? 0 : 1,
        };
        setSelectedIndex(index);
        dispatch(updatePermissionRequest(submitRequest, data.permissionId));
    };


    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={columns}
                    Title={'Permission List'}
                    data={parentList || []}
                    pageSize={25}
                    toggle={(roleIdforRole == 1 || _.includes(accessIds, '1')) ? createModel : false}
                />}

            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={'Permission'}
                modelSize={'md'}
                isEdit={isEdit}
                handleSubmit={handleValidation}>
                <FormLayout
                    dynamicForm={formContain}
                    handleSubmit={onFormSubmit}
                    optionListState={optionListState}
                    onChangeCallBack={{ "onBranchChange": onBranchChange, "onStaffChange": onStaffChange }}
                    setState={setState}
                    state={state}
                    ref={errorHandle}
                    noOfColumns={1}
                    errors={errors}
                    setErrors={setErrors}
                />
            </ModelViewBox>
        </React.Fragment>
    );
}

export default Index;
